import{_ as o,a0 as p,w as e,s as r,I as i,x as t,a1 as l,A as a,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Linux vs Mac：Linux 比 Mac 好的 7 個原因 | LCTT x X-CMD","titleTemplate":false,"description":"Linux vs Mac：Linux 比 Mac 好的 7 個原因 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux vs Mac：Linux 比 Mac 好的 7 個原因 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux vs Mac：Linux 比 Mac 好的 7 個原因 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180915 Linux vs Mac- 7 Reasons Why Linux is a Better Choice than Mac","title":"Linux vs Mac：Linux 比 Mac 好的 7 個原因","tag":"201810","desc":""},"relativePath":"201810/20180915 Linux vs Mac- 7 Reasons Why Linux is a Better Choice than Mac.md","filePath":"[post].md"}'),x={name:"201810/20180915 Linux vs Mac- 7 Reasons Why Linux is a Better Choice than Mac.md"};function d(m,n,L,f,M,g){const s=p("Link");return e(),r("div",null,[n[44]||(n[44]=i("h1",{id:"linux-vs-mac-linux-比-mac-好的-7-個原因",tabindex:"-1"},[t("Linux vs Mac：Linux 比 Mac 好的 7 個原因 "),i("a",{class:"header-anchor",href:"#linux-vs-mac-linux-比-mac-好的-7-個原因","aria-label":"Permalink to “Linux vs Mac：Linux 比 Mac 好的 7 個原因”"},"​")],-1)),i("p",null,[n[1]||(n[1]=t("最近我們談論了一些",-1)),l(s,{href:"https://itsfoss.com/linux-better-than-windows/"},{default:a(()=>[...n[0]||(n[0]=[t("為什麼 Linux 比 Windows 好",-1)])]),_:1}),n[2]||(n[2]=t("的原因。毫無疑問，Linux 是個非常優秀的平台。但是它和其它操作系統一樣也會有缺點。對於某些專門的領域，像是遊戲，Windows 當然更好。而對於視頻編輯等任務，Mac 系統可能更為方便。這一切都取決於你的偏好，以及你想用你的系統做些什麼。在這篇文章中，我們將會介紹一些 Linux 相對於 Mac 更好的一些地方。",-1))]),n[45]||(n[45]=u('<p>如果你已經在用 Mac 或者打算買一台 Mac 電腦，我們建議你仔細考慮一下，看看是改為使用 Linux 還是繼續使用 Mac。</p><h3 id="linux-比-mac-好的-7-個原因" tabindex="-1">Linux 比 Mac 好的 7 個原因 <a class="header-anchor" href="#linux-比-mac-好的-7-個原因" aria-label="Permalink to “Linux 比 Mac 好的 7 個原因”">​</a></h3><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/Linux-vs-mac-featured.png" alt="Linux vs Mac：為什麼 Linux 更好"></p><p>Linux 和 macOS 都是類 Unix 操作系統，並且都支持 Unix 命令、bash 和其它 shell，相比於 Windows，它們所支持的應用和遊戲比較少。但也就是這點比較相似。</p><p>平面設計師和視頻剪輯師更加傾向於使用 Mac 系統，而 Linux 更加適合做開發、系統管理、運維的工程師。</p><p>那要不要使用 Linux 呢，為什麼要選擇 Linux 呢？下面是根據實際經驗和理性分析給出的一些建議。</p><h4 id="_1、價格" tabindex="-1">1、價格 <a class="header-anchor" href="#_1、價格" aria-label="Permalink to “1、價格”">​</a></h4><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/linux-vs-mac-1.jpeg" alt="Linux vs Mac：為什麼 Linux 更好"></p><p>假設你只是需要瀏覽文件、看電影、下載圖片、寫文檔、製作報表或者做一些類似的工作，並且你想要一個更加安全的系統。</p><p>那在這種情況下，你覺得花費幾百美金買個系統完成這項工作，或者花費更多直接買個 MacBook 更好？當然，最終的決定權還是在你。</p><p>買個裝好 Mac 系統的電腦？還是買個便宜的電腦，然後自己裝上免費的 Linux 系統？這個要看你自己的偏好。就我個人而言，除了音視頻剪輯創作之外，Linux 都非常好地用，而對於音視頻方面，我更傾向於使用 Final Cut Pro（專業的視頻編輯軟件）和 Logic Pro X（專業的音樂製作軟件）（LCTT 譯註：這兩款軟件都是蘋果公司推出的）。</p><h4 id="_2、硬件支持" tabindex="-1">2、硬件支持 <a class="header-anchor" href="#_2、硬件支持" aria-label="Permalink to “2、硬件支持”">​</a></h4><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/linux-vs-mac-4.jpeg" alt="Linux vs Mac：為什麼 Linux 更好"></p>',13)),i("p",null,[n[4]||(n[4]=t("Linux 支持多種平台。無論你的電腦配置如何，你都可以在上面安裝 Linux，無論性能好或者差，Linux 都可以運行。",-1)),l(s,{href:"https://itsfoss.com/lightweight-linux-beginners/"},{default:a(()=>[...n[3]||(n[3]=[t("即使你的電腦已經使用很久了，你仍然可以通過選擇安裝合適的發行版讓 Linux 在你的電腦上流暢的運行",-1)])]),_:1}),n[5]||(n[5]=t("。",-1))]),n[46]||(n[46]=i("p",null,"而 Mac 不同，它是蘋果機專用系統。如果你希望買個便宜的電腦，然後自己裝上 Mac 系統，這幾乎是不可能的。一般來説 Mac 都是和蘋果設備配套的。",-1)),i("p",null,[n[7]||(n[7]=t("這有一些",-1)),l(s,{href:"https://hackintosh.com/"},{default:a(()=>[...n[6]||(n[6]=[t("在非蘋果系統上安裝 Mac OS 的教程",-1)])]),_:1}),n[8]||(n[8]=t("。這裏面需要用到的專業技術以及可能遇到的一些問題將會花費你許多時間，你需要想好這樣做是否值得。",-1))]),n[47]||(n[47]=i("p",null,"總之，Linux 所支持的硬件平台很廣泛，而 MacOS 相對而言則非常少。",-1)),n[48]||(n[48]=i("h4",{id:"_3、安全性",tabindex:"-1"},[t("3、安全性 "),i("a",{class:"header-anchor",href:"#_3、安全性","aria-label":"Permalink to “3、安全性”"},"​")],-1)),n[49]||(n[49]=i("p",null,[i("img",{src:"https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/linux-vs-mac-2.jpeg",alt:"Linux vs Mac：為什麼 Linux 更好"})],-1)),n[50]||(n[50]=i("p",null,"很多人都説 iOS 和 Mac 是非常安全的平台。的確，或許相比於 Windows，它確實比較安全，可並不一定有 Linux 安全。",-1)),i("p",null,[n[11]||(n[11]=t("我不是在危言聳聽。Mac 系統上也有不少惡意軟件和廣告，並且",-1)),l(s,{href:"https://www.computerworld.com/article/3262225/apple-mac/warning-as-mac-malware-exploits-climb-270.html"},{default:a(()=>[...n[9]||(n[9]=[t("數量與日俱增",-1)])]),_:1}),n[12]||(n[12]=t("。我認識一些不太懂技術的用户使用着很慢的 Mac 電腦並且為此深受折磨。一項快速調查顯示",-1)),l(s,{href:"https://www.imore.com/how-to-remove-browser-hijack"},{default:a(()=>[...n[10]||(n[10]=[t("瀏覽器惡意劫持軟件",-1)])]),_:1}),n[13]||(n[13]=t("是罪魁禍首。",-1))]),n[51]||(n[51]=i("p",null,"從來沒有絕對安全的操作系統，Linux 也不例外。Linux 也有漏洞，但是 Linux 發行版提供的及時更新彌補了這些漏洞。另外，到目前為止在 Linux 上還沒有自動運行的病毒或瀏覽器劫持惡意軟件的案例發生。",-1)),n[52]||(n[52]=i("p",null,"這可能也是一個你應該選擇 Linux 而不是 Mac 的原因。",-1)),n[53]||(n[53]=i("h4",{id:"_4、可定製性與靈活性",tabindex:"-1"},[t("4、可定製性與靈活性 "),i("a",{class:"header-anchor",href:"#_4、可定製性與靈活性","aria-label":"Permalink to “4、可定製性與靈活性”"},"​")],-1)),n[54]||(n[54]=i("p",null,[i("img",{src:"https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/linux-vs-mac-3.jpeg",alt:"Linux vs Mac：為什麼 Linux 更好"})],-1)),n[55]||(n[55]=i("p",null,"如果你有不喜歡的東西，自己定製或者修改它都行。",-1)),i("p",null,[n[17]||(n[17]=t("舉個例子，如果你不喜歡 Ubuntu 18.04.1 的 ",-1)),l(s,{href:"https://www.gnome.org/"},{default:a(()=>[...n[14]||(n[14]=[t("Gnome 桌面環境",-1)])]),_:1}),n[18]||(n[18]=t("，你可以換成 ",-1)),l(s,{href:"https://www.kde.org/plasma-desktop"},{default:a(()=>[...n[15]||(n[15]=[t("KDE Plasma",-1)])]),_:1}),n[19]||(n[19]=t("。你也可以嘗試一些 ",-1)),l(s,{href:"https://itsfoss.com/best-gnome-extensions/"},{default:a(()=>[...n[16]||(n[16]=[t("Gnome 擴展",-1)])]),_:1}),n[20]||(n[20]=t("豐富你的桌面選擇。這種靈活性和可定製性在 Mac OS 是不可能有的。",-1))]),n[56]||(n[56]=i("p",null,"除此之外，你還可以根據需要修改一些操作系統的代碼（但是可能需要一些專業知識）來打造適合你的系統。這個在 MacOS 上可以做嗎?",-1)),i("p",null,[n[23]||(n[23]=t("另外你可以根據需要從一系列的 Linux 發行版進行選擇。比如説，如果你喜歡 MacOS 上的工作方式，",-1)),l(s,{href:"https://elementary.io/"},{default:a(()=>[...n[21]||(n[21]=[t("Elementary OS",-1)])]),_:1}),n[24]||(n[24]=t(" 可能是個不錯的選擇。你想在你的舊電腦上裝上一個輕量級的 Linux 發行版系統嗎？這裏有一個",-1)),l(s,{href:"https://itsfoss.com/lightweight-linux-beginners/"},{default:a(()=>[...n[22]||(n[22]=[t("輕量級 Linux 發行版列表",-1)])]),_:1}),n[25]||(n[25]=t("。相比較而言，MacOS 缺乏這種靈活性。",-1))]),n[57]||(n[57]=u('<h4 id="_5、使用-linux-有助於你的職業生涯-針對-it-行業和科學領域的學生" tabindex="-1">5、使用 Linux 有助於你的職業生涯（針對 IT 行業和科學領域的學生） <a class="header-anchor" href="#_5、使用-linux-有助於你的職業生涯-針對-it-行業和科學領域的學生" aria-label="Permalink to “5、使用 Linux 有助於你的職業生涯（針對 IT 行業和科學領域的學生）”">​</a></h4><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/linux-vs-mac-5.jpeg" alt="Linux vs Mac：為什麼 Linux 更好"></p><p>對於 IT 領域的學生和求職者而言，這是有爭議的但是也是有一定的幫助的。使用 Linux 並不會讓你成為一個優秀的人，也不一定能讓你得到任何與 IT 相關的工作。</p><p>但是當你開始使用 Linux 並且探索如何使用的時候，你將會積累非常多的經驗。作為一名技術人員，你遲早會接觸終端，學習通過命令列操作文件系統以及安裝應用程序。你可能不會知道這些都是一些 IT 公司的新員工需要培訓的內容。</p><p>除此之外，Linux 在就業市場上還有很大的發展空間。Linux 相關的技術有很多（雲計算、Kubernetes、系統管理等），你可以學習、考取專業技能證書並獲得一份相關的高薪工作。要學習這些，你必須使用 Linux。</p><h4 id="_6、可靠" tabindex="-1">6、可靠 <a class="header-anchor" href="#_6、可靠" aria-label="Permalink to “6、可靠”">​</a></h4><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/linux-vs-mac-6.jpeg" alt="Linux vs Mac：為什麼 Linux 更好"></p><p>想想為什麼服務器上用的都是 Linux 系統，當然是因為它可靠。</p><p>但是它為什麼可靠呢，相比於 MacOS，它的可靠體現在什麼方面呢？</p><p>答案很簡單 —— 給用户更多的控制權，同時提供更好的安全性。在 MacOS 上，你並不能完全控制它，這樣做是為了讓操作變得更容易，同時提高你的用户體驗。使用 Linux，你可以做任何你想做的事情 —— 這可能會導致（對某些人來説）糟糕的用户體驗 —— 但它確實使其更可靠。</p><h4 id="_7、開源" tabindex="-1">7、開源 <a class="header-anchor" href="#_7、開源" aria-label="Permalink to “7、開源”">​</a></h4><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/linux-vs-mac-7.jpeg" alt="Linux vs Mac：為什麼 Linux 更好"></p><p>開源並不是每個人都關心的。但對我來説，Linux 最重要的優勢在於它的開源特性。上面討論的大多數觀點都是開源軟件的直接優勢。</p><p>簡單解釋一下，如果是開源軟件，你可以自己查看或者修改源代碼。但對 Mac 來説，蘋果擁有獨家控制權。即使你有足夠的技術知識，也無法查看 MacOS 的源代碼。</p><p>形象點説，Mac 驅動的系統可以讓你得到一輛車，但缺點是你不能打開引擎蓋看裏面是什麼。那可太差勁了!</p>',15)),i("p",null,[n[27]||(n[27]=t("如果你想深入瞭解開源軟件的優勢，可以在 OpenSource.com 上瀏覽一下 ",-1)),l(s,{href:"https://opensource.com/life/15/12/why-open-source"},{default:a(()=>[...n[26]||(n[26]=[t("Ben Balter 的文章",-1)])]),_:1}),n[28]||(n[28]=t("。",-1))]),n[58]||(n[58]=i("h3",{id:"總結",tabindex:"-1"},[t("總結 "),i("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),n[59]||(n[59]=i("p",null,"現在你應該知道為什麼 Linux 比 Mac 好了吧，你覺得呢？上面的這些原因可以説服你選擇 Linux 嗎？如果不行的話那又是為什麼呢？",-1)),n[60]||(n[60]=i("p",null,"請在下方評論讓我們知道你的想法。",-1)),n[61]||(n[61]=i("p",null,"提示：這裏的圖片是以“企鵝俱樂部”為原型的。",-1)),n[62]||(n[62]=i("hr",null,null,-1)),i("p",null,[n[30]||(n[30]=t("via: ",-1)),l(s,{href:"https://itsfoss.com/linux-vs-mac/"},{default:a(()=>[...n[29]||(n[29]=[t("https://itsfoss.com/linux-vs-mac/",-1)])]),_:1})]),i("p",null,[n[35]||(n[35]=t("作者：",-1)),l(s,{href:"https://itsfoss.com/author/ankush/"},{default:a(()=>[...n[31]||(n[31]=[t("Ankush Das",-1)])]),_:1}),n[36]||(n[36]=t(" 選題：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:a(()=>[...n[32]||(n[32]=[t("lujun9972",-1)])]),_:1}),n[37]||(n[37]=t(" 譯者：",-1)),l(s,{href:"https://github.com/Ryze-Borgia"},{default:a(()=>[...n[33]||(n[33]=[t("Ryze-Borgia",-1)])]),_:1}),n[38]||(n[38]=t(" 校對：",-1)),l(s,{href:"https://github.com/pityonline"},{default:a(()=>[...n[34]||(n[34]=[t("pityonline",-1)])]),_:1})]),i("p",null,[n[41]||(n[41]=t("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...n[39]||(n[39]=[t("LCTT",-1)])]),_:1}),n[42]||(n[42]=t(" 原創編譯，",-1)),l(s,{href:"https://linux.cn/"},{default:a(()=>[...n[40]||(n[40]=[t("Linux中國",-1)])]),_:1}),n[43]||(n[43]=t(" 榮譽推出",-1))])])}const T=o(x,[["render",d]]);export{v as __pageData,T as default};
